import { t } from "../i18n";
/**
 * 메일 화면 Actions — 계정/목록/상세/건수/동기화/메시지 조작. API 호출은 전부 여기서만 한다.
 */

import type { ActionContext } from "@ehfuse/forma";
import { ErrorAlert, SuccessAlert } from "@ehfuse/alerts";
import { mailApi, unwrap, type BulkMessageAction } from "../apis/mailApi";
import { defaultMailFolderCounts, storeMailScope } from "../models/defaults";
import {
    MAIL_PAGE_SIZE,
    type MailAccount,
    type MailFilters,
    type MailFolderCounts,
    type MailLabel,
    type MailMessageDetail,
    type MailMessageListItem,
    type MailThreadEntry,
    type MailMoveTarget,
    type MailRule,
    type MailState,
    type MailUserFolder,
} from "../models/types";

/** 목록 요청 시퀀스(오래된 응답 폐기용) */
let latestListRequestSeq = 0;
/** 상세 요청 시퀀스 */
let latestDetailRequestSeq = 0;

/**
 * "안 읽음" 목록에서 읽은 메일 — 다른 화면으로 가기 전까지 목록에 남긴다(2026-10-20 사용자 지정).
 * 서버는 안 읽음 거르기로 읽은 메일을 빼고 돌려주므로, 열자마자 오는 조용한 재조회(실시간 · 건수)에 줄이 바로 사라졌다.
 * 거르기가 바뀌거나 메일 화면을 떠나면(resetKeptReadMessages) 비운다.
 */
const keptReadRows = new Map<number, MailMessageListItem>();
let keptReadKey = "";

/** 남겨 둔 읽은 메일이 어느 목록의 것인지 가리는 열쇠 — 같은 안 읽음 목록일 때만 다시 끼운다. */
function keptKeyOf(filters: MailFilters): string {
    return `${filters.mailAccountSeq}|${filters.folder}|${filters.mailFolderSeq}|${filters.search}|${filters.labelSeq}`;
}

/** 안 읽음 목록에서 읽음이 된 줄을 적어 둔다. */
function keepReadRows(context: ActionContext<MailState>, rows: MailMessageListItem[]): void {
    const filters = context.getValue("filters") as MailFilters;
    if (!filters.unreadOnly) return;
    const key = keptKeyOf(filters);
    if (keptReadKey !== key) {
        keptReadRows.clear();
        keptReadKey = key;
    }
    for (const row of rows) keptReadRows.set(row.seq, { ...row, is_read: true });
}

/** 남겨 둔 읽은 메일을 버린다 — 메일 화면을 떠날 때 부른다. */
export function resetKeptReadMessages(): void {
    keptReadRows.clear();
    keptReadKey = "";
}

/** 오류 메시지 추출 */
function messageOf(error: unknown, fallback: string): string {
    return error instanceof Error && error.message ? error.message : fallback;
}

/** 내 메일 계정 목록을 읽는다. */
export const loadAccounts =
    () =>
    async (context: ActionContext<MailState>): Promise<MailAccount[]> => {
        context.setValue("loadingAccounts", true);
        try {
            const data = unwrap(await mailApi.listAccounts(), t("loadAccountsFailed"));
            const items = Array.isArray(data.items) ? data.items : [];
            context.setValue("accounts", items);
            return items;
        } catch (error) {
            ErrorAlert({ message: messageOf(error, t("loadAccountsFailed")) });
            return [];
        } finally {
            context.setValue("loadingAccounts", false);
        }
    };

/** 필터를 바꾼다(목록 재조회는 Layout 의 effect 가 필터 변화를 보고 호출한다). */
export const setFilters =
    () =>
    (context: ActionContext<MailState>, patch: Partial<MailFilters>): void => {
        const current = context.getValue("filters") as MailFilters;
        const next = { ...current, ...patch };
        const same =
            current.mailAccountSeq === next.mailAccountSeq &&
            current.folder === next.folder &&
            current.mailFolderSeq === next.mailFolderSeq &&
            current.search === next.search &&
            current.unreadOnly === next.unreadOnly &&
            current.starredOnly === next.starredOnly &&
            current.labelSeq === next.labelSeq;
        if (same) return;
        resetKeptReadMessages();
        context.setValue("filters", next);
        if (current.unreadOnly !== next.unreadOnly || current.starredOnly !== next.starredOnly || current.labelSeq !== next.labelSeq)
            storeMailScope(next);
        // 폴더/계정이 바뀌면 선택 상세는 의미가 없어진다.
        if (
            current.folder !== next.folder ||
            current.mailAccountSeq !== next.mailAccountSeq ||
            current.mailFolderSeq !== next.mailFolderSeq
        ) {
            context.setValue("selectedSeq", 0);
            context.setValue("detail", null);
            // 다른 폴더/계정의 목록이 새 목록이 오기 전까지 남아 보이지 않게 즉시 비운다
            // (모바일 서브페이지는 같은 전역 mail-state 를 쓰므로 이전 폴더 행이 그대로 보였다).
            context.setValue("messages", []);
            context.setValue("total", 0);
            context.setValue("page", 0);
            context.setValue("loadingList", true);
        }
    };

/** 목록을 읽는다. append=true 면 다음 페이지를 이어 붙인다. */
export const loadMessages =
    () =>
    async (context: ActionContext<MailState>, options?: { append?: boolean; silent?: boolean }): Promise<void> => {
        const filters = context.getValue("filters") as MailFilters;
        const append = Boolean(options?.append);
        const page = append ? (Number(context.getValue("page")) || 0) + 1 : 1;
        const requestSeq = ++latestListRequestSeq;
        if (!options?.silent) context.setValue("loadingList", true);
        context.setValue("error", "");
        try {
            const data = unwrap(
                await mailApi.listMessages({
                    mail_account_seq: filters.mailAccountSeq,
                    folder: filters.folder,
                    mail_folder_seq: filters.folder === "custom" ? filters.mailFolderSeq : undefined,
                    page,
                    limit: MAIL_PAGE_SIZE,
                    search: filters.search,
                    unread: filters.unreadOnly,
                    starred: filters.starredOnly,
                    label_seq: filters.labelSeq > 0 ? filters.labelSeq : undefined,
                    // 대화로 묶어 받는다(2026-10-20) — 같은 대화(답장 · 사본)는 한 줄, total 은 대화 수다.
                    thread: true,
                }),
                t("loadListFailed")
            );
            if (requestSeq !== latestListRequestSeq) return;
            let items = Array.isArray(data.items) ? data.items : [];
            let kept = 0;
            if (filters.unreadOnly && keptReadKey === keptKeyOf(filters) && keptReadRows.size > 0) {
                // 서버가 뺀 읽은 줄을 일시 순서대로 다시 끼운다(다음 페이지 붙이기에는 끼우지 않는다 — 이미 목록에 있다).
                if (!append) {
                    const got = new Set(items.map((row) => row.seq));
                    const extra = [...keptReadRows.values()].filter((row) => !got.has(row.seq));
                    kept = extra.length;
                    items = [...items, ...extra].sort((a, b) => String(b.date_time ?? "").localeCompare(String(a.date_time ?? "")));
                }
            } else if (!filters.unreadOnly) {
                resetKeptReadMessages();
            }
            if (append) {
                const prev = context.getValue("messages") as MailMessageListItem[];
                const seen = new Set(prev.map((row) => row.seq));
                context.setValue("messages", [...prev, ...items.filter((row) => !seen.has(row.seq))]);
            } else {
                context.setValue("messages", items);
            }
            context.setValue("total", (Number(data.total) || 0) + kept || items.length);
            context.setValue("page", page);
        } catch (error) {
            if (requestSeq !== latestListRequestSeq) return;
            context.setValue("error", messageOf(error, t("loadListFailed")));
        } finally {
            if (requestSeq === latestListRequestSeq) context.setValue("loadingList", false);
        }
    };

/** 폴더/계정 건수를 읽고 계정별 미읽음도 갱신한다. */
export const loadCounts =
    () =>
    async (context: ActionContext<MailState>): Promise<void> => {
        const filters = context.getValue("filters") as MailFilters;
        try {
            const data = unwrap(await mailApi.counts(filters.mailAccountSeq), t("loadCountsFailed"));
            context.setValue("counts", { ...defaultMailFolderCounts, ...(data.folders ?? {}) } as MailFolderCounts);
            const accounts = context.getValue("accounts") as MailAccount[];
            const byAccount = data.by_account ?? {};
            context.setValue(
                "accounts",
                accounts.map((acc) => ({ ...acc, unread_count: Number(byAccount[String(acc.seq)] ?? 0) }))
            );
            // 사용자 메일함별 미읽음(사이드바 배지)
            const byFolder = data.by_folder ?? {};
            const folders = context.getValue("folders") as MailUserFolder[];
            context.setValue(
                "folders",
                folders.map((f) => ({ ...f, unread_count: Number(byFolder[String(f.seq)] ?? 0) }))
            );
        } catch {
            // 건수는 보조 정보 — 실패해도 조용히 둔다.
        }
    };

/** 목록 행을 부분 갱신한다(상세가 같은 메시지면 함께). */
function patchLocalMessage(context: ActionContext<MailState>, seq: number, patch: Partial<MailMessageListItem>): void {
    const rows = context.getValue("messages") as MailMessageListItem[];
    context.setValue(
        "messages",
        rows.map((row) => (row.seq === seq ? { ...row, ...patch } : row))
    );
    const detail = context.getValue("detail") as MailMessageDetail | null;
    if (detail && detail.seq === seq) context.setValue("detail", { ...detail, ...patch });
}

/** 번역본 보기 상태 변경을 목록 행에 반영한다(번역 제목 표시/원문 제목 복귀 — 상세 패널이 호출). */
export const setTranslatedSubject =
    () =>
    (context: ActionContext<MailState>, seq: number, translatedSubject: string | null): void => {
        patchLocalMessage(context, seq, { translated_subject: translatedSubject });
    };

/** 목록에서 행들을 제거한다(선택 중이면 선택 해제). */
function removeLocalMessages(context: ActionContext<MailState>, seqs: number[]): void {
    const remove = new Set(seqs);
    const rows = context.getValue("messages") as MailMessageListItem[];
    const next = rows.filter((row) => !remove.has(row.seq));
    context.setValue("messages", next);
    context.setValue("total", Math.max(0, (Number(context.getValue("total")) || 0) - (rows.length - next.length)));
    if (remove.has(Number(context.getValue("selectedSeq")))) {
        context.setValue("selectedSeq", 0);
        context.setValue("detail", null);
    }
}

/** 메시지를 선택해 상세를 읽는다(받은편지함 메시지는 열면서 읽음 처리). */
export const selectMessage =
    () =>
    async (context: ActionContext<MailState>, seq: number): Promise<void> => {
        if (!(seq > 0)) {
            context.setValue("selectedSeq", 0);
            context.setValue("detail", null);
            context.setValue("thread", []);
            return;
        }
        const requestSeq = ++latestDetailRequestSeq;
        context.setValue("selectedSeq", seq);
        context.setValue("loadingDetail", true);
        const rows = context.getValue("messages") as MailMessageListItem[];
        const row = rows.find((r) => r.seq === seq);
        const wasUnread = Boolean(row && !row.is_read);
        // 요청 전에 적는다 — 서버가 읽음으로 바꾸며 보내는 실시간 재조회가 응답보다 먼저 와도 줄이 남게
        if (wasUnread && row) keepReadRows(context, [row]);
        try {
            const detail = unwrap(await mailApi.getMessage(seq, true), t("loadMailFailed"));
            if (requestSeq !== latestDetailRequestSeq) return;
            context.setValue("detail", detail);
            patchLocalMessage(context, seq, { is_read: true });
            // 대화(2026-10-20) — 같은 대화의 메일들을 띠로 보이고, 목록에서 연 대화면 대화 전체를 읽음으로 한다(지메일과 같다).
            // 띠에서 다른 메일을 고른 것이면(이미 그 대화) 다시 읽지 않는다.
            const currentThread = context.getValue("thread") as MailThreadEntry[];
            const inSameThread = currentThread.some((item) => item.seq === seq);
            const threadUnread = Number(row?.thread_unread ?? 0);
            if (!inSameThread) {
                context.setValue("thread", []);
                void mailApi
                    .getThread(seq, threadUnread > 0)
                    .then((res) => {
                        if (requestSeq !== latestDetailRequestSeq) return;
                        const items = unwrap(res, t("loadThreadFailed")).items;
                        context.setValue("thread", items.length > 1 ? items : []);
                        if (threadUnread > 0) {
                            patchLocalMessage(context, seq, { thread_unread: 0 });
                            void loadCounts()(context);
                        }
                    })
                    .catch(() => undefined);
            } else {
                context.setValue("thread", currentThread.map((item) => (item.seq === seq ? { ...item, is_read: true } : item)));
            }
            if (wasUnread && row) {
                // 미읽음 건수 낙관 감소(서버 재집계는 loadCounts 로) — 메일이 있는 폴더의 배지만 줄인다.
                if (row.folder === "custom" && row.mail_folder_seq > 0) {
                    const folders = context.getValue("folders") as MailUserFolder[];
                    context.setValue(
                        "folders",
                        folders.map((f) =>
                            f.seq === row.mail_folder_seq
                                ? { ...f, unread_count: Math.max(0, (f.unread_count ?? 0) - 1) }
                                : f
                        )
                    );
                } else if (row.folder === "inbox") {
                    const counts = context.getValue("counts") as MailFolderCounts;
                    context.setValue("counts", { ...counts, inbox_unread: Math.max(0, counts.inbox_unread - 1) });
                    const accounts = context.getValue("accounts") as MailAccount[];
                    context.setValue(
                        "accounts",
                        accounts.map((acc) =>
                            acc.seq === row.mail_account_seq
                                ? { ...acc, unread_count: Math.max(0, (acc.unread_count ?? 0) - 1) }
                                : acc
                        )
                    );
                }
            }
        } catch (error) {
            if (requestSeq !== latestDetailRequestSeq) return;
            ErrorAlert({ message: messageOf(error, t("loadMailFailed")) });
            context.setValue("selectedSeq", 0);
            context.setValue("detail", null);
        } finally {
            if (requestSeq === latestDetailRequestSeq) context.setValue("loadingDetail", false);
        }
    };

/** 선택을 해제한다. */
export const clearSelection =
    () =>
    (context: ActionContext<MailState>): void => {
        context.setValue("selectedSeq", 0);
        context.setValue("detail", null);
        context.setValue("thread", []);
    };

/** 메시지 일괄/단건 액션(읽음·중요·휴지통·복원·영구삭제)을 적용하고 목록을 낙관 갱신한다. */
export const applyMessageAction =
    () =>
    async (
        context: ActionContext<MailState>,
        seqs: number[],
        action: BulkMessageAction,
        move?: MailMoveTarget,
        threads = false
    ): Promise<boolean> => {
        const targets = Array.from(new Set(seqs.filter((s) => s > 0)));
        if (targets.length === 0) return false;
        // 묶은 목록에서 대화의 머리 한 통만 따로 처리했다 — 같은 대화의 다른 메일이 남아 있으면 그 줄이 다시 보이게 목록을 새로 받는다.
        const rows = context.getValue("messages") as MailMessageListItem[];
        const singleOfThread = !threads && rows.some((row) => targets.includes(row.seq) && Number(row.thread_count ?? 1) > 1);
        try {
            unwrap(await mailApi.bulkMessages(targets, action, move, threads), t("actionFailed"));
        } catch (error) {
            ErrorAlert({ message: messageOf(error, t("actionFailed")) });
            return false;
        }
        if (action === "read" || action === "unread") {
            if (action === "read") {
                const rows = context.getValue("messages") as MailMessageListItem[];
                keepReadRows(context, rows.filter((row) => targets.includes(row.seq)));
            }
            else for (const seq of targets) keptReadRows.delete(seq);
            for (const seq of targets) patchLocalMessage(context, seq, { is_read: action === "read" });
        } else if (action === "star" || action === "unstar") {
            for (const seq of targets) patchLocalMessage(context, seq, { is_starred: action === "star" });
        } else {
            removeLocalMessages(context, targets);
            const folders = context.getValue("folders") as MailUserFolder[];
            // 한 문장 열쇠 + 건수 — 언어마다 어순이 달라 "N건을" + "…했습니다" 로 잇지 않는다
            const count = targets.length;
            const toTrash = () => t("bulkMovedTrash", { count });
            const toSpam = () => t("bulkMovedSpam", { count });
            const moveMessage = () =>
                move?.folder === "custom"
                    ? t("bulkMovedFolder", { count, name: folders.find((f) => f.seq === move.mail_folder_seq)?.name ?? t("mailbox") })
                    : move?.folder === "spam"
                      ? toSpam()
                      : move?.folder === "trash"
                        ? toTrash()
                        : t("bulkMovedInbox", { count });
            SuccessAlert(
                action === "move"
                    ? moveMessage()
                    : action === "trash"
                      ? toTrash()
                      : action === "spam"
                        ? toSpam()
                        : action === "restore"
                          ? t("bulkRestored", { count })
                          : t("bulkDeletedForever", { count })
            );
            if (singleOfThread) void loadMessages()(context, { silent: true });
        }
        return true;
    };

/** 계정(0=전체 활성 계정)을 즉시 동기화하고 목록/건수를 다시 읽는다. */
export const syncNow =
    () =>
    async (context: ActionContext<MailState>, mailAccountSeq: number): Promise<void> => {
        const accounts = context.getValue("accounts") as MailAccount[];
        const targets =
            mailAccountSeq > 0 ? accounts.filter((a) => a.seq === mailAccountSeq) : accounts.filter((a) => a.enabled);
        if (targets.length === 0) {
            ErrorAlert({ message: t("noAccountToSync") });
            return;
        }
        // 동기화 중 표시는 계정별로 — 눌린 계정(또는 전체 대상)만 켜고, 각 계정이 끝날 때마다 내린다.
        const targetSeqs = targets.map((a) => a.seq);
        const markDone = (seq: number) =>
            context.setValue(
                "syncingSeqs",
                (context.getValue("syncingSeqs") as number[]).filter((s) => s !== seq)
            );
        context.setValue("syncingSeqs", [
            ...new Set([...(context.getValue("syncingSeqs") as number[]), ...targetSeqs]),
        ]);
        let added = 0;
        const errors: string[] = [];
        try {
            for (const account of targets) {
                try {
                    const result = unwrap(await mailApi.syncAccount(account.seq), t("syncFailed"));
                    added += Number(result.added) || 0;
                    if (result.error) errors.push(`${account.email}: ${result.error}`);
                    if (result.account) {
                        const current = context.getValue("accounts") as MailAccount[];
                        context.setValue(
                            "accounts",
                            current.map((a) =>
                                a.seq === account.seq ? { ...a, ...result.account, unread_count: a.unread_count } : a
                            )
                        );
                    }
                } catch (error) {
                    errors.push(`${account.email}: ${messageOf(error, t("syncFailedShort"))}`);
                } finally {
                    markDone(account.seq);
                }
            }
        } finally {
            targetSeqs.forEach(markDone);
        }
        if (errors.length > 0) ErrorAlert({ message: errors.join("\n") });
        else SuccessAlert(added > 0 ? t("newMailReceived", { count: added }) : t("noNewMail"));
    };

/** 사용자 메일함 목록을 읽는다. */
export const loadFolders =
    () =>
    async (context: ActionContext<MailState>): Promise<MailUserFolder[]> => {
        try {
            const data = unwrap(await mailApi.listFolders(), t("loadFoldersFailed"));
            const items = Array.isArray(data.items) ? data.items : [];
            context.setValue("folders", items);
            return items;
        } catch {
            return context.getValue("folders") as MailUserFolder[];
        }
    };

/** 내 색상 라벨을 읽는다(config.labels 를 켠 화면만 부른다). 보던 라벨 탭의 라벨이 지워졌으면 전체로 되돌린다. */
export const loadLabels =
    () =>
    async (context: ActionContext<MailState>): Promise<MailLabel[]> => {
        try {
            const data = unwrap(await mailApi.listLabels(), t("loadLabelsFailed"));
            const items = Array.isArray(data.items) ? data.items : [];
            context.setValue("labels", items);
            const filters = context.getValue("filters") as MailFilters;
            if (filters.labelSeq > 0 && !items.some((l) => l.seq === filters.labelSeq)) {
                const next = { ...filters, labelSeq: 0 };
                context.setValue("filters", next);
                storeMailScope(next);
            }
            return items;
        } catch {
            // 라벨은 보조 기능 — 못 읽어도 메일 목록은 그대로 쓴다.
            return context.getValue("labels") as MailLabel[];
        }
    };

/**
 * 메일들에 라벨을 달고 뗀다 — 성공하면 목록 행의 label_seqs 를 바로 고친다(다시 읽지 않는다).
 * 라벨 탭을 보던 중에 그 라벨을 뗀 메일은 목록에서 뺀다(그 탭에 더는 속하지 않는다).
 */
export const applyLabels =
    () =>
    async (context: ActionContext<MailState>, seqs: number[], add: number[], remove: number[]): Promise<boolean> => {
        const targets = Array.from(new Set(seqs.filter((s) => s > 0)));
        if (targets.length === 0 || (add.length === 0 && remove.length === 0)) return false;
        try {
            unwrap(await mailApi.applyLabels(targets, add, remove), t("labelChangeFailed"));
        } catch (error) {
            ErrorAlert({ message: messageOf(error, t("labelChangeFailed")) });
            return false;
        }
        const rows = context.getValue("messages") as MailMessageListItem[];
        for (const seq of targets) {
            const row = rows.find((r) => r.seq === seq);
            const current = row?.label_seqs ?? [];
            const next = [...current.filter((l) => !remove.includes(l)), ...add.filter((l) => !current.includes(l))];
            patchLocalMessage(context, seq, { label_seqs: next });
        }
        const filters = context.getValue("filters") as MailFilters;
        if (filters.labelSeq > 0 && remove.includes(filters.labelSeq)) {
            const remove2 = new Set(targets);
            const list = context.getValue("messages") as MailMessageListItem[];
            const next = list.filter((row) => !remove2.has(row.seq));
            context.setValue("messages", next);
            context.setValue("total", Math.max(0, (Number(context.getValue("total")) || 0) - (list.length - next.length)));
        }
        return true;
    };

/** 규칙 목록을 읽는다. */
export const loadRules =
    () =>
    async (context: ActionContext<MailState>): Promise<MailRule[]> => {
        try {
            const data = unwrap(await mailApi.listRules(), t("loadRulesFailed"));
            const items = Array.isArray(data.items) ? data.items : [];
            context.setValue("rules", items);
            return items;
        } catch (error) {
            ErrorAlert({ message: messageOf(error, t("loadRulesFailed")) });
            return [];
        }
    };
