import { t } from "../i18n";
/**
 * 메일 작성 다이얼로그 컨트롤러 — 새 메일/답장/전체답장/전달/임시보관 열기, 발송, 임시저장.
 */

import { useCallback, useRef, useState } from "react";
import { useGlobalForm, useModal, type ActionContext } from "@ehfuse/forma";
import { ErrorAlert, SuccessAlert, WarningAlert } from "@ehfuse/alerts";
import { mailApi, unwrap } from "../apis/mailApi";
import type { MuaModalControl } from "../types/modal";
import { defaultComposeForm } from "../models/defaults";
import type {
    ComposeForm,
    ComposeMode,
    ComposeRequest,
    MailAccount,
    MailMessageDetail,
    ComposeAttachment,
} from "../models/types";
import { formatAddressLabel, splitAddressInput } from "../utils/format";
import { buildQuotedBody, prefixSubject } from "../utils/html";

interface ComposeControllerOptions {
    onSent?: () => void; // 발송 후(보낸편지함/임시보관 재조회)
    onDraftSaved?: () => void; // 임시저장 후
}

/** 서명 블록을 본문 끝에 붙일 HTML 로 만든다. */
function signatureBlock(account: MailAccount | undefined): string {
    const sig = String(account?.signature ?? "").trim();
    return sig ? `<p><br></p><div class="mail-signature">${sig}</div>` : "";
}

/** 수신확인을 마지막에 켰는지 기억하는 자리 — 늘 켜 두고 쓰는 사람이 창마다 다시 켜지 않게. */
const READ_RECEIPT_KEY = "mua.compose.readReceipt";

function loadReadReceiptPref(): boolean {
    try {
        return localStorage.getItem(READ_RECEIPT_KEY) === "1";
    } catch {
        return false;
    }
}

function saveReadReceiptPref(on: boolean): void {
    try {
        localStorage.setItem(READ_RECEIPT_KEY, on ? "1" : "0");
    } catch {
        // 저장소를 못 쓰는 환경이면 기억하지 않을 뿐이다.
    }
}

/** 새 창의 기본값 — 수신확인만 지난번 선택을 따른다(보안메일·비밀번호는 매번 새로 정한다). */
const freshComposeForm = (): ComposeForm => ({ ...defaultComposeForm, read_receipt: loadReadReceiptPref() });

/** 예약 칸의 값("YYYY-MM-DD HH:mm", 이 기기의 시간대)을 시각으로 읽는다. 비었거나 틀리면 null. */
function parseScheduleInput(value: string): Date | null {
    const date = new Date(
        String(value ?? "")
            .trim()
            .replace(" ", "T")
    );
    return Number.isNaN(date.getTime()) ? null : date;
}

/** 서버의 예약 시각(UTC "YYYY-MM-DD HH:mm:ss")을 예약 칸의 값으로 바꾼다. */
function toScheduleInput(value: string | null | undefined): string {
    if (!value) return "";
    const date = new Date(`${value.replace(" ", "T")}Z`);
    if (Number.isNaN(date.getTime())) return "";
    const pad = (n: number) => String(n).padStart(2, "0");
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/** 서명 블록 HTML — 비면 빈 글. */
function wrapSignature(html: string): string {
    const sig = String(html ?? "").trim();
    return sig && sig !== "<p><br></p>" ? `<div class="mail-signature">${sig}</div>` : "";
}

/**
 * 본문에서 서명을 꺼낸다(config.signatureBelowEditor) — 서명 칸에 따로 두고 보낼 때 다시 넣으려고.
 * 서명 뒤에 인용문(blockquote)이 있으면 답장 · 전달이라 그 앞에 다시 넣을 자리로 기억한다. 서명이 없으면 끝에 넣을 빈 서명.
 */
export function extractSignature(bodyHtml: string): { body: string; signature: string; place: "end" | "before_quote" } {
    if (typeof DOMParser === "undefined") return { body: bodyHtml, signature: "", place: "end" };
    const doc = new DOMParser().parseFromString(`<div id="mua-root">${bodyHtml}</div>`, "text/html");
    const root = doc.getElementById("mua-root");
    if (!root) return { body: bodyHtml, signature: "", place: "end" };
    const quoted = Boolean(root.querySelector("blockquote"));
    const sigEl = root.querySelector(".mail-signature");
    if (!sigEl) return { body: bodyHtml, signature: "", place: quoted ? "before_quote" : "end" };
    const signature = sigEl.innerHTML;
    // 서명 앞에 붙여 둔 빈 줄(<p><br></p>)도 함께 뺀다 — 남기면 꺼낼 때마다 빈 줄이 하나씩 쌓인다.
    const prev = sigEl.previousElementSibling;
    if (prev && prev.tagName === "P" && prev.textContent?.trim() === "" && prev.innerHTML.replace(/\s/g, "") === "<br>") prev.remove();
    sigEl.remove();
    return { body: root.innerHTML || "<p><br></p>", signature, place: quoted ? "before_quote" : "end" };
}

/** 서명 칸의 서명을 본문에 다시 넣는다 — 답장 · 전달이면 인용 머리(blockquote 바로 앞 줄) 앞에, 아니면 끝에. */
function mergeSignature(values: ComposeForm): string {
    if (!values.signature_place) return values.body_html;
    const block = wrapSignature(values.signature_html);
    if (!block) return values.body_html;
    if (values.signature_place === "before_quote" && typeof DOMParser !== "undefined") {
        const doc = new DOMParser().parseFromString(`<div id="mua-root">${values.body_html}</div>`, "text/html");
        const root = doc.getElementById("mua-root");
        const quote = root?.querySelector("blockquote");
        if (root && quote) {
            // 인용 머리("…님이 작성:" · "전달된 메일") 줄이 blockquote 바로 앞에 있다 — 그 앞에 넣어야 서명이 인용 밖에 선다.
            const anchor = quote.previousElementSibling ?? quote;
            const holder = doc.createElement("div");
            holder.innerHTML = `<p><br></p>${block}`;
            for (const node of Array.from(holder.childNodes)) anchor.parentNode?.insertBefore(node, anchor);
            return root.innerHTML;
        }
    }
    return `${values.body_html}<p><br></p>${block}`;
}

/** 폼 값을 요청 본문으로 변환한다. 수신확인·보안메일은 보낼 때만 싣는다(임시저장은 내용만 둔다). */
export function toComposeRequest(values: ComposeForm, forSend = false): ComposeRequest {
    return {
        ...(forSend && values.scheduled ? { send_at: parseScheduleInput(values.send_at)?.toISOString() ?? null } : {}),
        ...(forSend && (values.read_receipt || values.secure) ? { read_receipt: true } : {}),
        ...(forSend && values.secure
            ? { secure: { password: values.secure_password, hint: values.secure_hint.trim() } }
            : {}),
        mail_account_seq: values.mail_account_seq,
        ...(values.seq > 0 ? { seq: values.seq } : {}),
        to: splitAddressInput(values.to),
        cc: splitAddressInput(values.cc),
        bcc: splitAddressInput(values.bcc),
        subject: values.subject,
        body_html: mergeSignature(values),
        attachments: values.attachments.map((a) => ({
            uuid: a.uuid,
            name: a.name,
            mime: a.mime,
            content_base64: a.content_base64,
            ...(a.source_message_seq ? { source_message_seq: a.source_message_seq } : {}),
            ...(a.eml_message_seq ? { eml_message_seq: a.eml_message_seq } : {}),
        })),
        in_reply_to: values.in_reply_to || null,
        references: values.references,
    };
}

/** 새 메일 작성 열기 */
const openNew =
    (modal: ReturnType<typeof useModal>) =>
    (
        context: ActionContext<ComposeForm>,
        account: MailAccount | undefined,
        to = "",
        // 제목·본문 미리 채우기(2026-10-05) — 다른 화면의 내용을 메일로 보낼 때. 없으면 예전처럼 빈 본문 + 서명.
        draft?: { subject?: string; html?: string }
    ): void => {
        context.reset();
        context.setValues({
            ...freshComposeForm(),
            mode: "new",
            mail_account_seq: account?.seq ?? 0,
            to,
            ...(draft?.subject ? { subject: draft.subject } : {}),
            body_html: `${draft?.html || "<p><br></p>"}${signatureBlock(account)}`,
        });
        modal.open();
    };

/** 답장/전체답장/전달 열기 */
const openFromMessage =
    (modal: ReturnType<typeof useModal>) =>
    (
        context: ActionContext<ComposeForm>,
        detail: MailMessageDetail,
        mode: Exclude<ComposeMode, "new" | "draft">,
        account: MailAccount | undefined
    ): void => {
        const replyTarget = detail.reply_to ?? detail.from;
        const myAddress = String(account?.email ?? "").toLowerCase();
        const others = [...detail.to, ...detail.cc].filter(
            (a) => a.address.toLowerCase() !== myAddress && a.address !== replyTarget?.address
        );
        const references = [...(detail.references ?? []), ...(detail.message_id ? [detail.message_id] : [])];
        context.reset();
        context.setValues({
            ...freshComposeForm(),
            mode,
            mail_account_seq: account?.seq ?? detail.mail_account_seq,
            to: mode === "forward" ? "" : formatAddressLabel(replyTarget),
            cc: mode === "replyAll" ? others.map(formatAddressLabel).join(", ") : "",
            showCcBcc: mode === "replyAll" && others.length > 0,
            subject: prefixSubject(detail.subject, mode === "forward" ? "Fwd" : "Re"),
            body_html: `${signatureBlock(account)}${buildQuotedBody(detail, mode === "forward" ? "forward" : "reply")}`,
            // 전달은 원문 첨부를 그대로 싣는다(uuid 참조 — 서버가 ES 에서 내려받아 첨부한다).
            attachments:
                mode === "forward"
                    ? detail.attachments.map((a) => ({
                          uuid: a.uuid,
                          name: a.name,
                          mime: a.mime,
                          size: a.size,
                          source_message_seq: detail.seq,
                      }))
                    : [],
            in_reply_to: mode === "forward" ? "" : (detail.message_id ?? ""),
            references: mode === "forward" ? [] : references,
        });
        modal.open();
    };

/** 여러 통 전달 열기 — 원문 각각을 .eml 첨부로 싣는다(본문은 서명만). 서버가 eml_message_seq 로 원문을 조립한다. */
const openForwardMany =
    (modal: ReturnType<typeof useModal>) =>
    (context: ActionContext<ComposeForm>, details: MailMessageDetail[], account: MailAccount | undefined): void => {
        if (details.length === 0) return;
        const first = details[0];
        const attachments: ComposeAttachment[] = details.map((d) => ({
            eml_message_seq: d.seq,
            name: `${
                String(d.subject ?? "")
                    .replace(/[\\/:*?"<>|\r\n]/g, "_")
                    .trim() || `mail-${d.seq}`
            }.eml`,
            mime: "message/rfc822",
            // 크기는 본문 길이 + 첨부 합계로 어림한다(서버가 조립하기 전엔 정확히 알 수 없다).
            size: (d.body_html?.length ?? 0) + d.attachments.reduce((sum, a) => sum + (a.size || 0), 0),
        }));
        const subject = prefixSubject(first.subject, "Fwd") + (details.length > 1 ? t("fwdMoreSuffix", { count: details.length - 1 }) : "");
        context.reset();
        context.setValues({
            ...freshComposeForm(),
            mode: "forward",
            mail_account_seq: account?.seq ?? first.mail_account_seq,
            to: "",
            cc: "",
            showCcBcc: false,
            subject,
            body_html: `<p><br></p>${signatureBlock(account)}`,
            attachments,
            in_reply_to: "",
            references: [],
        });
        modal.open();
    };

/** 임시보관 메일 이어쓰기 열기 */
const openDraft =
    (modal: ReturnType<typeof useModal>) =>
    (context: ActionContext<ComposeForm>, detail: MailMessageDetail): void => {
        context.reset();
        context.setValues({
            ...freshComposeForm(),
            seq: detail.seq,
            mode: "draft",
            mail_account_seq: detail.mail_account_seq,
            to: detail.to.map(formatAddressLabel).join(", "),
            cc: detail.cc.map(formatAddressLabel).join(", "),
            bcc: detail.bcc.map(formatAddressLabel).join(", "),
            showCcBcc: detail.cc.length + detail.bcc.length > 0,
            subject: detail.subject ?? "",
            body_html: detail.body_html || "",
            attachments: detail.attachments.map((a) => ({ uuid: a.uuid, name: a.name, mime: a.mime, size: a.size })),
            in_reply_to: detail.in_reply_to ?? "",
            references: detail.references ?? [],
            // 예약해 둔 메일이면 예약 시각과 옵션을 그대로 편다. 보안메일 비밀번호는 서버가 돌려주지 않아 다시 넣어야 한다.
            ...(detail.send_at
                ? {
                      scheduled: true,
                      send_at: toScheduleInput(detail.send_at),
                      read_receipt: Boolean(detail.scheduled?.read_receipt),
                      secure: Boolean(detail.scheduled?.secure),
                      secure_hint: detail.scheduled?.hint ?? "",
                  }
                : {}),
        });
        modal.open();
    };

/** 메일 작성 컨트롤러 훅. */
export function useComposeController({ onSent, onDraftSaved }: ComposeControllerOptions = {}) {
    const modal: MuaModalControl = useModal({ modalId: "mail-compose-dialog" });
    const [sending, setSending] = useState(false);
    const [savingDraft, setSavingDraft] = useState(false);
    // 방금 보냈는가 — 보내고 닫힐 때 자동 저장이 보낸 메일을 임시보관함에 다시 남기지 않게(0.3.155).
    const sentRef = useRef(false);

    const form = useGlobalForm<ComposeForm>({
        formId: "mail-compose-form",
        initialValues: defaultComposeForm,
        onSubmit: async (values) => {
            if (!(values.mail_account_seq > 0)) {
                WarningAlert({ message: t("pickSendAccount") });
                return false;
            }
            const request = toComposeRequest(values, true);
            if (request.to.length + request.cc.length + request.bcc.length === 0) {
                WarningAlert({ message: t("enterRecipient") });
                return false;
            }
            if (values.scheduled) {
                const at = parseScheduleInput(values.send_at);
                if (!at || at.getTime() < Date.now() + 60_000) {
                    WarningAlert({ message: t("scheduleInFuture") });
                    return false;
                }
            }
            if (values.secure && values.secure_password.length < 4) {
                WarningAlert({ message: t("securePasswordMin") });
                return false;
            }
            setSending(true);
            try {
                const sent = unwrap(await mailApi.send(request), t("sendMailFailed"));
                if (!values.secure) saveReadReceiptPref(values.read_receipt);
                const failed = sent.failed_recipients ?? [];
                // 받는 사람마다 따로 보내므로 일부만 실패할 수 있다 — 누구에게 안 갔는지 알려야 다시 보낸다.
                if (failed.length > 0)
                    WarningAlert({ message: t("someRecipientsFailed", { list: failed.join(", ") }) });
                else
                    // 첨부가 큰 메일은 서버가 뒤에서 보낸다(pending) — 보낸편지함에 "보내는 중" 으로 보이고, 실패하면 거기 "발송 실패" 로 남는다.
                    SuccessAlert(
                        sent.scheduled ? t("scheduledAt", { time: values.send_at }) : sent.pending ? t("sendingInBackground") : t("mailSent")
                    );
                sentRef.current = true;
                modal.close();
                onSent?.();
                return true;
            } catch (error) {
                ErrorAlert({ message: error instanceof Error ? error.message : t("sendMailFailed") });
                return false;
            } finally {
                setSending(false);
            }
        },
        actions: {
            openNew: openNew(modal),
            openFromMessage: openFromMessage(modal),
            openForwardMany: openForwardMany(modal),
            openDraft: openDraft(modal),
        },
    });

    /**
     * 임시보관함에 저장한다(성공 시 seq 를 폼에 반영해 이후 저장은 갱신이 된다).
     * silent(자동 저장, 0.3.155) — 알림 창을 띄우지 않고 성공 여부만 돌려준다.
     */
    const saveDraft = useCallback(async (options: { silent?: boolean; onProgress?: (percent: number) => void } = {}): Promise<boolean> => {
        const silent = Boolean(options.silent);
        const values = form.getFormValues();
        if (!(values.mail_account_seq > 0)) {
            if (!silent) WarningAlert({ message: t("pickSendAccount") });
            return false;
        }
        setSavingDraft(true);
        try {
            // 새로 붙인 첨부(아직 서버에 없는 것)가 있으면 multipart 로 보내 올라간 양(%)을 알린다(0.4.18).
            const hasNewFiles = (values.attachments ?? []).some((a) => !a.uuid && !a.eml_message_seq);
            const request = toComposeRequest(values);
            const saved = unwrap(
                hasNewFiles && options.onProgress
                    ? await mailApi.saveDraftWithProgress(request, (loaded, total) => options.onProgress?.(total > 0 ? Math.min(100, Math.round((loaded / total) * 100)) : 0))
                    : await mailApi.saveDraft(request),
                t("draftSaveFailed")
            );
            form.setFormValue("seq", saved.seq);
            form.setFormValue("mode", "draft");
            // 새로 올린 첨부는 서버 uuid 로 바뀌었으므로 base64 를 버리고 서버 메타로 교체한다.
            form.setFormValue(
                "attachments",
                (saved.attachments ?? []).map((a) => ({ uuid: a.uuid, name: a.name, mime: a.mime, size: a.size }))
            );
            onDraftSaved?.();
            if (silent) return true;
            // 임시저장은 예약을 푼다(서버) — 예약해 둔 메일을 고쳐 저장했으면 그 사실을 알린다.
            SuccessAlert(
                values.mode === "draft" && values.scheduled
                    ? t("draftUnscheduled")
                    : t("draftSaved")
            );
            return true;
        } catch (error) {
            if (!silent) ErrorAlert({ message: error instanceof Error ? error.message : t("draftSaveFailed") });
            return false;
        } finally {
            setSavingDraft(false);
        }
    }, [form, onDraftSaved]);

    return { form, modal, sending, savingDraft, saveDraft, sentRef };
}

/** 컨트롤러 타입 */
export type ComposeController = ReturnType<typeof useComposeController>;
