import { t } from "../i18n";
/**
 * 메일 관리 UI 호스트 — 관리 다이얼로그(계정/메일함/규칙 탭)·계정 등록/수정 폼·규칙 폼·**새 메일 작성**을 한 곳에서 그린다.
 *
 * 왜 메일 화면(Layout)에서 떼어냈나: 사이드바 메일 그룹의 + 처럼 메일 화면 **밖**에서도 관리를 여는 자리가 있다.
 * 다이얼로그가 Layout 안에 있으면 그때는 요청만 쌓이고 메일 화면에 들어가야 열려 고장처럼 보였다(2026-09-06).
 * 앱이 대시보드 레이아웃에 이 호스트를 한 번 두면(MuaConfig.appHostsMailManage) 어느 화면에서든 그 자리에서 열린다.
 * 앱이 두지 않으면 Layout 이 스스로 하나 그린다 — 여는 쪽은 언제나 internal/manageRequest 로 요청만 한다.
 *
 * 데이터는 메일 화면·사이드바 훅과 같은 전역 상태(MAIL_STATE_ID)라 따로 읽지 않는다. 다만 규칙은 메일 화면만
 * 읽어 두므로 메일 밖에서 열 때 비어 있을 수 있어 그때만 한 번 읽는다. 목록(메시지) 새로고침은 메일 화면이
 * 떠 있을 때만 의미가 있어 requestMailRefresh 로 넘긴다(구독자가 없으면 아무 일도 없다).
 *
 * ⚠️ MuaProvider 안에서 써야 한다(앱 FormDialog·로그인 계정을 거기서 받는다).
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Box, Drawer } from "@mui/material";
import { ConfirmDialog, ErrorAlert } from "@ehfuse/alerts";
import { useModal } from "@ehfuse/forma";
import { mailApi, unwrap } from "../apis/mailApi";
import { useMailController } from "../controllers/mailController";
import { useMailAccountFormController } from "../controllers/mailAccountFormController";
import { useSenderContacts } from "../controllers/senderContacts";
import type { MailAccount, MailLabel, MailListFolder, MailMessageDetail, MailRule, MailRuleFormPrefill, MailUserFolder } from "../models/types";
import { MAIL_FOLDER_LABELS } from "../models/subPage";
import { useMuaConfig } from "../MuaProvider";
import { useIsMobile } from "../internal/useIsMobile";
import { DefaultMobileDetailDialog } from "../internal/mobileDefaults";
import { MessageDetailPanel } from "./components/MessageDetailPanel";
import { consumeMailManageRequest, subscribeMailManage, type MailComposeDraft, type MailManageTab } from "../internal/manageRequest";
import { requestMailRefresh } from "../internal/refreshRequest";
import { MailManageDialog } from "./dialogs/MailManageDialog";
import { MailAccountFormDialog } from "./dialogs/MailAccountFormDialog";
import { MailHostedProfileDialog } from "./dialogs/MailHostedProfileDialog";
import { MailRuleFormDialog } from "./dialogs/MailRuleFormDialog";
import { ComposeDialog } from "./dialogs/ComposeDialog";
import { useComposeController } from "../controllers/composeController";

/** 메일 관리 다이얼로그·폼을 그리는 호스트. 앱 레이아웃 또는 메일 화면 어느 한 곳에만 둔다. */
export function MailManageHost() {
    const { state } = useMailController();
    // 관리 다이얼로그는 현재 팀과 무관하게 내 모든 팀 공용을 보여준다(팀명 칩으로 구분) — in_sidebar 로 거르지 않는다.
    const allAccounts = state.useValue("accounts") as MailAccount[];
    const allFolders = state.useValue("folders") as MailUserFolder[];
    const rules = state.useValue("rules") as MailRule[];
    const labels = state.useValue("labels") as MailLabel[];
    const syncingSeqs = state.useValue("syncingSeqs") as number[];
    // 규칙 폼의 이동 대상은 보기 범위 메일함만(메일 화면과 같다).
    const folders = useMemo(() => allFolders.filter((f) => f.in_sidebar !== false), [allFolders]);

    /** 계정·건수를 다시 읽는다(계정 저장/삭제/동기화 후). */
    const refreshAccounts = useCallback(() => {
        void state.actions.loadAccounts().then(() => state.actions.loadCounts());
    }, [state.actions]);
    /** 메일함 변경 후 — 메일함·건수를 다시 읽고, 메일 화면이 떠 있으면 목록도. */
    const refreshFolders = useCallback(() => {
        void state.actions.loadFolders().then(() => state.actions.loadCounts());
        void requestMailRefresh();
    }, [state.actions]);
    /** 규칙 변경 후 — 규칙을 다시 읽고, 메일 화면이 떠 있으면 목록도(규칙 적용 결과). */
    const refreshRules = useCallback(() => {
        void state.actions.loadRules();
        void requestMailRefresh();
    }, [state.actions]);

    /** 계정 순서 저장 — 서버가 새 목록을 돌려주므로 다시 조회하지 않는다(사이드바도 같은 목록을 쓴다). */
    const handleReorderAccounts = useCallback(
        (seqs: number[]) => {
            void mailApi
                .reorderAccounts(seqs)
                .then((res) => {
                    const items = unwrap(res, "").items;
                    if (Array.isArray(items)) state.setValue("accounts", items);
                })
                .catch(() => refreshAccounts()); // 실패하면 서버 순서로 되돌린다.
        },
        [state, refreshAccounts]
    );

    const accountForm = useMailAccountFormController({ onSaved: refreshAccounts });
    // 기업메일 사서함은 외부 계정 폼이 아니라 프로필(이름·서명·기본 발신) 창으로 연다 — 고칠 수 있는 것이 다르다.
    // 닫아도 계정은 비우지 않는다 — 다이얼로그가 입력 중이던 값을 지키고, 닫히는 동안 주소 칸이 비지 않게.
    const [hostedEditing, setHostedEditing] = useState<MailAccount | null>(null);
    const [hostedOpen, setHostedOpen] = useState(false);

    /** 계정 목록의 연필 — 기업메일 사서함이면 프로필 창, 그 외에는 외부 계정 폼. */
    const handleEditAccount = useCallback(
        (account: MailAccount) => {
            if (account.kind === "hosted") {
                setHostedEditing(account);
                setHostedOpen(true);
            }
            else accountForm.form.actions.openDialog(account);
        },
        [accountForm.form.actions]
    );

    /**
     * 새 메일 작성 — 메일 화면이 아니라 이 호스트가 그린다(2026-09-06).
     * 사이드바 "새 메일" 은 업무함·결재 어디서든 눌리므로, 다이얼로그가 메일 화면 안에 있으면
     * 받은편지함까지 가야 열려 고장처럼 보인다(관리 다이얼로그를 여기로 옮긴 것과 같은 이유).
     * 보낸 뒤·임시저장 뒤에는 메일 화면이 떠 있을 때만 목록을 새로 읽는다(구독자가 없으면 아무 일도 없다).
     */
    const compose = useComposeController({
        onSent: () => void requestMailRefresh(),
        onDraftSaved: () => void requestMailRefresh(),
    });
    // 새 메일의 보내는 계정 — 마지막에 고른 것 > 기본 발신 > 첫 계정(메일 화면과 같은 규칙).
    const lastAccountSeq = state.useValue("lastAccountSeq") as number;
    const sidebarAccounts = useMemo(() => allAccounts.filter((a) => a.in_sidebar !== false), [allAccounts]);
    const openCompose = useCallback(
        (to?: string, draft?: MailComposeDraft) => {
            const account =
                sidebarAccounts.find((a) => a.seq === lastAccountSeq) ??
                sidebarAccounts.find((a) => a.is_default) ??
                sidebarAccounts[0];
            // 계정이 하나도 없으면 등록부터 — 빈 작성 창을 열어 봐야 보낼 수 없다.
            if (!account) {
                accountForm.form.actions.openDialog(null);
                return;
            }
            // 받는 사람 미리 채우기(앱 본문의 이메일 주소를 눌렀을 때, 2026-09-13).
            compose.form.actions.openNew(account, to ?? "", draft);
        },
        [sidebarAccounts, lastAccountSeq, compose.form.actions, accountForm.form.actions]
    );

    // 관리 다이얼로그(계정 / 메일함 / 규칙 중 하나 — 탭 없이 고른 목록만, 2026-10-01). 계정 등록·수정 창은 그 위에 겹쳐 연다.
    const manageModal = useModal({ modalId: "mail-manage-dialog" });
    const [manageTab, setManageTab] = useState<MailManageTab>("accounts");
    const openManage = useCallback(
        (tab: MailManageTab) => {
            setManageTab(tab);
            manageModal.open();
            // 규칙은 메일 화면만 읽어 둔다 — 메일 밖에서 열었으면 비어 있으므로 여기서 한 번 읽는다.
            if (((state.getValue("rules") as MailRule[] | undefined) ?? []).length === 0) {
                void state.actions.loadRules();
            }
            // 라벨도 메일 화면이 읽어 둔다 — 밖에서 라벨 관리를 열었을 때를 위해 다시 읽는다(작아서 늘 읽어도 싸다).
            if (tab === "labels") void state.actions.loadLabels();
        },
        [manageModal, state]
    );

    // 규칙 폼(관리 다이얼로그의 [규칙 추가]/수정, 메일 우클릭 "규칙 만들기")
    const [ruleEditing, setRuleEditing] = useState<{
        rule: MailRule | null;
        prefill: MailRuleFormPrefill | null;
    } | null>(null);

    /** 관리 목록에서 계정 삭제(확인 후) — 삭제 성공 시 폼 컨트롤러가 목록을 재조회한다. */
    const handleDeleteAccount = useCallback(
        (account: MailAccount) => {
            ConfirmDialog({
                title: t("deleteAccount"),
                message: t("deleteAccountNamedConfirm", { name: account.name || account.email }),
                onConfirm: () => void accountForm.removeAccount(account.seq),
            });
        },
        [accountForm]
    );

    /**
     * 편지 한 통 보기(2026-10-06) — 메일 화면 밖에서 편지를 그 자리에 연다(requestMailMessageView).
     * 메일 화면의 목록 상태(선택·상세)와 섞이지 않게 여기서 따로 읽어 쥔다 — 메일 화면이 떠 있지 않을 때 쓰는 창이다.
     * 넓은 화면은 메일 화면의 목록형과 같은 오른쪽 드로어, 폰은 같은 상세 다이얼로그(mfd 슬라이드)로 띄운다.
     */
    const isMobile = useIsMobile();
    const { mobile: mobileConfig } = useMuaConfig();
    const MobileDetailDialog = mobileConfig?.DetailDialog ?? DefaultMobileDetailDialog;
    const [viewing, setViewing] = useState<{ seq: number; detail: MailMessageDetail | null; loading: boolean } | null>(null);
    const viewRequest = useRef(0);
    const closeView = useCallback(() => {
        viewRequest.current += 1;
        setViewing(null);
    }, []);
    const openView = useCallback((seq: number, markRead = true) => {
        const request = ++viewRequest.current;
        setViewing((prev) => (prev?.seq === seq ? { ...prev, loading: !prev.detail } : { seq, detail: null, loading: true }));
        void mailApi
            .getMessage(seq, markRead)
            .then((res) => {
                // 그 사이 닫았거나 다른 편지를 열었으면 버린다.
                if (request !== viewRequest.current) return;
                setViewing({ seq, detail: unwrap(res, t("loadMailFailed")), loading: false });
                if (markRead) void state.actions.loadCounts();
            })
            .catch((error) => {
                if (request !== viewRequest.current) return;
                setViewing(null);
                ErrorAlert({ message: error instanceof Error ? error.message : t("loadMailFailed") });
            });
    }, [state.actions]);
    const viewDetail = viewing?.detail ?? null;
    const viewAccount = useMemo(
        () => allAccounts.find((a) => a.seq === viewDetail?.mail_account_seq) ?? sidebarAccounts.find((a) => a.is_default) ?? sidebarAccounts[0],
        [allAccounts, sidebarAccounts, viewDetail]
    );
    // 메일 화면과 같은 주소록 판정 — 없는 주소면 추가 아이콘, 있는 주소면 외부 이미지를 바로 보인다.
    const viewContacts = useSenderContacts(viewDetail?.from?.address, viewAccount);
    /** 편지를 다른 곳으로 보내는 동작(휴지통·스팸·복원·삭제·읽지 않음) — 끝나면 창을 닫고 건수·메일 화면 목록을 맞춘다. */
    const viewActThenClose = useCallback(
        (action: "trash" | "spam" | "restore" | "delete" | "unread") => {
            if (!viewDetail) return;
            void state.actions.applyMessageAction([viewDetail.seq], action).then((ok: boolean) => {
                if (!ok) return;
                closeView();
                void state.actions.loadCounts();
                void requestMailRefresh();
            });
        },
        [viewDetail, state.actions, closeView]
    );
    const viewPanel = viewing ? (
        <MessageDetailPanel
            detail={viewDetail}
            loading={viewing.loading}
            embedded={isMobile}
            onClose={closeView}
            onReply={(mode) => viewDetail && viewAccount && compose.form.actions.openFromMessage(viewDetail, mode, viewAccount)}
            onEditDraft={() => viewDetail && compose.form.actions.openDraft(viewDetail)}
            onComposeTo={(address) => openCompose(address)}
            trustedSender={viewContacts.trustedSender}
            onAddContact={viewContacts.canAddContact ? (address, name) => void viewContacts.addContact(address, name) : undefined}
            onToggleStar={() =>
                viewDetail &&
                void state.actions
                    .applyMessageAction([viewDetail.seq], viewDetail.is_starred ? "unstar" : "star")
                    // 별표는 이 창이 쥔 상세에 바로 반영한다(목록 상태만 고쳐서는 이 창이 안 바뀐다).
                    .then((ok: boolean) => ok && setViewing((prev) => (prev?.detail ? { ...prev, detail: { ...prev.detail, is_starred: !prev.detail.is_starred } } : prev)))
            }
            onMarkUnread={() => viewActThenClose("unread")}
            onTrash={() => viewActThenClose("trash")}
            onSpam={() => viewActThenClose("spam")}
            onRestore={() => viewActThenClose("restore")}
            onDeleteForever={() => viewActThenClose("delete")}
            onCreateRule={() =>
                viewDetail &&
                // 조건은 비워 두고 [조건 추가]에서 고르면 이 편지의 값이 채워진다(메일 화면의 "규칙 만들기" 와 같다).
                setRuleEditing({
                    rule: null,
                    prefill: { hints: { from_address: String(viewDetail.from?.address ?? ""), from_name: String(viewDetail.from?.name ?? ""), subject: viewDetail.subject ?? "" } },
                })
            }
        />
    ) : null;

    // 열기 요청 소비 — 마운트 때 대기 중인 것 + 이후 들어오는 것.
    useEffect(() => {
        const check = () => {
            const request = consumeMailManageRequest();
            if (!request) return;
            if (request.kind === "compose") openCompose(request.to, request.draft);
            else if (request.kind === "manage") openManage(request.tab);
            else if (request.kind === "account") accountForm.form.actions.openDialog(request.account);
            else if (request.kind === "message") openView(request.seq);
            else setRuleEditing({ rule: request.rule, prefill: request.prefill });
        };
        check();
        return subscribeMailManage(check);
    }, [openManage, openCompose, openView, accountForm.form.actions]);

    return (
        <>
            {isMobile ? (
                <MobileDetailDialog
                    modalId="mail-message-view"
                    open={Boolean(viewing)}
                    title={MAIL_FOLDER_LABELS[viewDetail?.folder as MailListFolder] ?? t("mail")}
                    onClose={closeView}
                >
                    <Box sx={{ bgcolor: "#fff", borderRadius: 2, overflow: "hidden", boxShadow: "0 1px 3px rgba(15,23,42,0.12)" }}>{viewPanel}</Box>
                </MobileDetailDialog>
            ) : (
                <Drawer
                    anchor="right"
                    open={Boolean(viewing)}
                    onClose={closeView}
                    slotProps={{ paper: { sx: { width: "min(850px, 50vw)", maxWidth: "50vw", display: "flex", flexDirection: "column" } } }}
                >
                    {viewPanel}
                </Drawer>
            )}
            <ComposeDialog controller={compose} accounts={sidebarAccounts} />
            <MailManageDialog
                open={manageModal.isOpen}
                tab={manageTab}
                onTabChange={setManageTab}
                onClose={manageModal.close}
                accounts={allAccounts}
                syncingSeqs={syncingSeqs}
                folders={allFolders}
                rules={rules}
                onAddAccount={() => accountForm.form.actions.openDialog(null)}
                onEditAccount={handleEditAccount}
                onDeleteAccount={handleDeleteAccount}
                onSyncAccount={(account) => void state.actions.syncNow(account.seq).then(() => requestMailRefresh())}
                onReorderAccounts={handleReorderAccounts}
                onFoldersChanged={refreshFolders}
                onAddRule={() => setRuleEditing({ rule: null, prefill: null })}
                onEditRule={(rule) => setRuleEditing({ rule, prefill: null })}
                onRulesChanged={refreshRules}
                labels={labels}
                onLabelsChanged={(items) => {
                    // 순서 바꾸기는 새 목록을 돌려받는다 — 그대로 쓰고, 그 밖(만들기·고치기·지우기)은 다시 읽는다.
                    if (items) state.setValue("labels", items);
                    else void state.actions.loadLabels();
                    // 라벨을 지우면 메일 행의 칩도 사라져야 한다 — 메일 화면이 떠 있으면 목록을 다시 읽는다.
                    if (!items) void requestMailRefresh();
                }}
            />
            <MailAccountFormDialog controller={accountForm} />
            <MailHostedProfileDialog
                open={hostedOpen}
                account={hostedEditing}
                onClose={() => setHostedOpen(false)}
                onSaved={refreshAccounts}
            />
            <MailRuleFormDialog
                open={Boolean(ruleEditing)}
                rule={ruleEditing?.rule ?? null}
                prefill={ruleEditing?.prefill ?? null}
                folders={folders}
                onClose={() => setRuleEditing(null)}
                onSaved={refreshRules}
            />
        </>
    );
}
