import { formDialogLocale, t } from "../../i18n";
/**
 * 메일 관리 다이얼로그 — 계정 / 메일함 / 규칙 중 **하나**를 창 하나로 연다(2026-10-01).
 * 전에는 세 목록을 상단 탭(switchContent)으로 한 창에 두었는데, 메일함·규칙을 찾으려면 창을 열고 탭을 다시 골라야 했다.
 * 이제 사이드바 메일 ⋮ 메뉴가 "메일 계정 관리 / 메일함 관리 / 메일 규칙" 을 따로 고르고, 창은 고른 목록만 보인다(탭 없음).
 * 액션바 왼쪽 [+ …]는 그 목록에 맞춰 바뀌고(계정 추가 / 메일함 만들기 / 규칙 추가), 오른쪽은 [닫기].
 */

import { useState } from "react";
import { Button, Stack } from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import { useIsMobile } from "../../internal/useIsMobile";
import { useMuaFormDialog } from "../../MuaProvider";
import type { MailAccount, MailLabel, MailRule, MailUserFolder } from "../../models/types";
import { MailLabelFormDialog, MailLabelsList } from "./MailLabelsList";
import { MailAccountsList } from "./MailAccountsList";
import { MailFolderFormDialog, MailFoldersList } from "./MailFoldersList";
import { MailRulesList } from "./MailRulesList";

/** 관리 탭 키 */
export type MailManageTab = "accounts" | "folders" | "rules" | "labels";
const ADD_LABEL: Record<MailManageTab, string> = {
    get accounts() { return t("addAccountButton"); },
    get folders() { return t("createFolderButton"); },
    get rules() { return t("addRuleButton"); },
    get labels() { return t("createLabelButton"); },
};
const TITLE: Record<MailManageTab, string> = {
    get accounts() { return t("manageAccounts"); },
    get folders() { return t("manageFolders"); },
    get rules() { return t("mailRules"); },
    get labels() { return t("manageLabels"); },
};

interface MailManageDialogProps {
    open: boolean; // 열림
    tab: MailManageTab; // 보일 목록(계정 / 메일함 / 규칙)
    onTabChange?: (tab: MailManageTab) => void; // 예전 탭 전환(탭을 없애 쓰지 않는다 — 호출부 호환용)
    onClose: () => void; // 닫기
    accounts: MailAccount[]; // 계정 목록
    syncingSeqs: number[]; // 동기화 중인 계정 seq
    folders: MailUserFolder[]; // 사용자 메일함
    rules: MailRule[]; // 규칙
    onAddAccount: () => void; // 계정 추가
    onEditAccount: (account: MailAccount) => void; // 계정 수정
    onDeleteAccount: (account: MailAccount) => void; // 계정 삭제
    onSyncAccount: (account: MailAccount) => void; // 지금 동기화
    onReorderAccounts?: (seqs: number[]) => void; // 계정 표시 순서 저장(드래그)
    onFoldersChanged: () => void; // 메일함 변경 후
    onAddRule: () => void; // 규칙 추가
    onEditRule: (rule: MailRule) => void; // 규칙 수정
    onRulesChanged: () => void; // 규칙 변경 후
    labels?: MailLabel[]; // 색상 라벨(config.labels — 라벨 목록)
    onLabelsChanged?: (items?: MailLabel[]) => void; // 라벨 변경 후(items 가 있으면 그 목록이 새 것)
}

/** 메일 관리 다이얼로그 */
export function MailManageDialog({
    open,
    tab,
    onClose,
    accounts,
    syncingSeqs,
    folders,
    rules,
    onAddAccount,
    onEditAccount,
    onDeleteAccount,
    onSyncAccount,
    onReorderAccounts,
    onFoldersChanged,
    onAddRule,
    onEditRule,
    onRulesChanged,
    labels = [],
    onLabelsChanged,
}: MailManageDialogProps) {
    // 모바일은 풀스크린 우→좌 슬라이드(서브페이지 위에 한 겹 더 뜬다).
    const isMobile = useIsMobile();
    const FormDialog = useMuaFormDialog();
    const [folderAddOpen, setFolderAddOpen] = useState(false);
    const [labelAddOpen, setLabelAddOpen] = useState(false);
    const handleAdd = () => {
        if (tab === "accounts") onAddAccount();
        else if (tab === "folders") setFolderAddOpen(true);
        else if (tab === "labels") setLabelAddOpen(true);
        else onAddRule();
    };
    const addButton = (
        <Button
            variant="outlined"
            startIcon={<AddIcon />}
            onClick={handleAdd}
            fullWidth={isMobile}
            sx={{ color: "#111", borderColor: "#cbd5e1", whiteSpace: "nowrap", ...(isMobile ? { minHeight: 48 } : {}) }}
        >
            {ADD_LABEL[tab]}
        </Button>
    );
    const closeButton = (
        <Button
            variant="contained"
            onClick={onClose}
            fullWidth={isMobile}
            sx={isMobile ? { minHeight: 48, whiteSpace: "nowrap" } : { minWidth: 80 }}
        >
            {t("close")}
        </Button>
    );
    return (
        <>
            <FormDialog
                fontScaleKey="MailManageDialog"
                fullScreen={isMobile}
                mobilePresentation={isMobile ? "slide" : "dialog"}
                // 모바일 액션바 — 왼쪽 슬롯·래퍼를 전폭으로 늘려야 50/50 Stack 이 화면 폭을 받는다(새 메일과 같은 처리).
                sx={
                    isMobile
                        ? {
                              DialogActions: {
                                  "& .left-actions": { flex: 1, minWidth: 0, width: "100%" },
                                  "& .left-actions > *": { flex: 1, minWidth: 0, width: "100%" },
                                  "& .right-actions": { display: "none" },
                              },
                          }
                        : undefined
                }
                open={open}
                onClose={onClose}
                title={{ text: TITLE[tab] }}
                titleIcons={{ delete: { visible: false } }}
                tabs={{ visible: false }}
                locale={formDialogLocale()}
                // 계정 줄이 [아이콘][이름·주소·서버][칩][액션] 네 칸이라 sm(600)에서는 주소가 눌리고
                // md(900)는 남는 자리가 커 헐거워 보인다 — mfd 의 width 로 그 사이를 직접 잡는다(2026-09-07).
                // sx 로는 안 된다 — mfd 의 sx 는 DialogTitle/Content/Actions 세 칸짜리 설정 객체라 조용히 무시된다.
                width={isMobile ? undefined : 750}
                maxWidth="md"
                scrollPastLastSection={false}
                contentBottomPadding={24}
                sections={[
                    {
                        key: "accounts" as MailManageTab,
                        id: "mail-manage-accounts",
                        tabTitle: t("accountTab"),
                        showTitle: false,
                        children: (
                            <MailAccountsList
                                accounts={accounts}
                                syncingSeqs={syncingSeqs}
                                onEdit={onEditAccount}
                                onDelete={onDeleteAccount}
                                onSync={onSyncAccount}
                                onReorder={onReorderAccounts}
                            />
                        ),
                    },
                    {
                        key: "folders" as MailManageTab,
                        id: "mail-manage-folders",
                        tabTitle: t("foldersTab"),
                        showTitle: false,
                        children: <MailFoldersList folders={folders} onChanged={onFoldersChanged} />,
                    },
                    {
                        key: "rules" as MailManageTab,
                        id: "mail-manage-rules",
                        tabTitle: t("rulesTab"),
                        showTitle: false,
                        children: (
                            <MailRulesList
                                rules={rules}
                                folders={folders}
                                onEdit={onEditRule}
                                onChanged={onRulesChanged}
                            />
                        ),
                    },
                    {
                        key: "labels" as MailManageTab,
                        id: "mail-manage-labels",
                        tabTitle: t("labelsTab"),
                        showTitle: false,
                        children: <MailLabelsList labels={labels} onChanged={(items) => onLabelsChanged?.(items)} />,
                    },
                ]
                    .filter((section) => section.key === tab)
                    .map(({ key: _key, ...section }) => section)}
                actions={{
                    visible: true,
                    showCancelButton: false,
                    // 모바일은 [+ …][닫기] 50/50 균등 배치
                    ...(isMobile
                        ? {
                              left: (
                                  <>
                                      {/* 간격은 spacing(자식 여백)이 아니라 gap 으로 준다(0.3.129) — mfd 액션바가 단추 여백을 0 으로 지워 두 단추가 붙었다. */}
                                      <Stack direction="row" sx={{ width: "100%", gap: 1.5 }}>
                                          {addButton}
                                          {closeButton}
                                      </Stack>
                                  </>
                              ),
                          }
                        : { left: addButton, right: closeButton }),
                }}
            />
            <MailFolderFormDialog
                open={folderAddOpen}
                onClose={() => setFolderAddOpen(false)}
                onChanged={onFoldersChanged}
            />
            <MailLabelFormDialog open={labelAddOpen} onClose={() => setLabelAddOpen(false)} onSaved={() => onLabelsChanged?.()} />
        </>
    );
}
